package com.smarthub.plus;
import org.json.*;
import org.junit.Test;
import static org.junit.Assert.*;
public class DirectProvidersTest {
 @Test public void arabicMbcNameKeepsTheArabicNetworkSeparateFromUnrelatedMbcBrands()throws Exception{JSONArray c=new JSONArray("[{id:'MBC3.ae',name:'MBC 3',owners:['MBC Group']},{id:'MBC3.mu',name:'MBC 3',owners:['Mauritius Broadcasting Corporation']}]");JSONArray l=new JSONArray("[{channel:'MBC3.ae',in_use:true,url:'https://example.org/ae.png',width:100,height:100},{channel:'MBC3.mu',in_use:true,url:'https://example.org/mu.png',width:400,height:400}]");JSONObject arabic=ChannelCatalogue.match("إم بي سي 3","",c,l);assertEquals("MBC3.ae",arabic.getString("channel"));assertEquals("https://example.org/ae.png",arabic.getJSONArray("images").getJSONObject(0).getString("url"));assertEquals("matched",ChannelCatalogue.match("MBC 3","",c,l).getString("status"));}
 @Test public void epgNameVariationsKeepTheSameIdentityAndDifferentSequelsStayDistinct(){assertEquals(BetterPostersProvider.titleTokens("Fantastic Beasts: Dumbledore’s Secrets"),BetterPostersProvider.titleTokens("Fantastic Beasts: The Secrets of Dumbledore"));assertNotEquals(BetterPostersProvider.titleTokens("Film Part 2"),BetterPostersProvider.titleTokens("Film Part 3"));}
 @Test public void duplicateEnglishNamesAutomaticallyUseAnAvailableLogo()throws Exception{JSONArray c=new JSONArray("[{id:'a',name:'ABC',owners:['Owner A']},{id:'b',name:'ABC',owners:['Owner B']}]");JSONArray l=new JSONArray("[{channel:'a',in_use:true,url:'https://example.org/a.png',width:100,height:100}]");assertEquals("matched",ChannelCatalogue.match("ABC HD","",c,l).getString("status"));}
 @Test public void regionalSharedBrandDoesNotInventARegionalProgrammeIdentity()throws Exception{JSONArray c=new JSONArray("[{id:'a',name:'Network 3',owners:['Example Corporation']},{id:'b',name:'Network 3',owners:['Example EMEA']}]");JSONArray l=new JSONArray("[{channel:'a',in_use:true,url:'https://example.org/a.png',width:100,height:100}]");JSONObject result=ChannelCatalogue.match("Network3 HD","",c,l);assertEquals("matched",result.getString("status"));assertEquals("",result.getString("channel"));assertTrue(result.getBoolean("brandOnly"));}
}
